VALUES
  ('stage_called_denom_primary', 'Впервые созвонился за период, первичные (служебная)', NULL, 'external', 'int', NULL, '{}', '{}', false, true, true, false, 0, 'sum', false, false, true, false, 'Конверсии стадий', 1090, 'Знаменатель «CR Созвонился → Продажа (перв.)»: сделки первичных воронок, ВПЕРВЫЕ вошедшие в любую «созвонился»-стадию в периоде. Стадии «созвонился» резолвятся динамически (stages.name ILIKE ''%созвонился%''). Данные с 03.04.2026. Инжектится сервером (calledConversion.ts), только отчёт по менеджерам.'),
