-- Миграция 107: «Кол-во сделок в стадии X» за период (42 шт) + «CR Созвонился →
-- Продажа» (4 служебные + 3 CR). Задача владельца 28.07. БД: YC analytics
-- (node migrations/run_analytics.mjs migrations/107_stage_period_metrics.sql).
--
-- Семейство 1 — «Вошло в стадию: …» (перв./повт./все): потоковая пара к снимкам
-- «Стадии (сейчас)» (#2063). Семантика: сделки, ВПЕРВЫЕ (MIN(event_at) по
-- sa.deal_events) вошедшие в стадию в периоде — та же, что у знаменателей
-- «Конверсий стадий» (migrations/064). Реестр стадий — STAGE_SNAPSHOT_GROUPS
-- (stageSnapshot.ts), движок features/reports/engine/stageEntered.ts,
-- инжект только by-managers. Тройки перв./повт./все — JOIN funnels.is_repeat.
--
-- Семейство 2 — «CR Созвонился → Продажа» (перв./повт./все): движок
-- features/reports/engine/calledConversion.ts; «созвонился» = стадии с
-- ILIKE '%созвонился%' (7 стадий воронок 0/1/2/3, «Не дозвонился» не подпадает).
-- Числитель: из знаменателя те, что когда-либо ПОСЛЕ входа получили sold_at.
--
-- Данные deal_events с 03.04.2026 — раньше метрики честно null.
--
-- РЕГЛАМЕНТ КОМАНДЫ (WORKLOG #2059): пользовательские метрики скрыты в общем
-- каталоге (is_test=true + is_hidden_in_ui=true) до прод-деплоя кода-инжекта.
-- ШАГ РАЗВОРОТА при прод-релизе — UPDATE в конце файла (закомментирован).
-- Идемпотентна; is_hidden_in_ui/is_test вне ON CONFLICT SET — переезд не прячет
-- уже развёрнутые метрики.

ON CONFLICT (id) DO UPDATE SET name_ru = EXCLUDED.name_ru, name_short_ru = EXCLUDED.name_short_ru, metric_type = EXCLUDED.metric_type, data_type = EXCLUDED.data_type, formula = EXCLUDED.formula, dependencies = EXCLUDED.dependencies, aggregation_fn = EXCLUDED.aggregation_fn, category = EXCLUDED.category, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, is_collect_ok = EXCLUDED.is_collect_ok, is_calc_ok = EXCLUDED.is_calc_ok, description = EXCLUDED.description;

ON CONFLICT (id) DO UPDATE SET name_ru = EXCLUDED.name_ru, name_short_ru = EXCLUDED.name_short_ru, metric_type = EXCLUDED.metric_type, data_type = EXCLUDED.data_type, formula = EXCLUDED.formula, dependencies = EXCLUDED.dependencies, aggregation_fn = EXCLUDED.aggregation_fn, category = EXCLUDED.category, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, is_collect_ok = EXCLUDED.is_collect_ok, is_calc_ok = EXCLUDED.is_calc_ok, description = EXCLUDED.description;

ON CONFLICT (id) DO UPDATE SET name_ru = EXCLUDED.name_ru, name_short_ru = EXCLUDED.name_short_ru, metric_type = EXCLUDED.metric_type, data_type = EXCLUDED.data_type, formula = EXCLUDED.formula, dependencies = EXCLUDED.dependencies, aggregation_fn = EXCLUDED.aggregation_fn, category = EXCLUDED.category, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, is_collect_ok = EXCLUDED.is_collect_ok, is_calc_ok = EXCLUDED.is_calc_ok, description = EXCLUDED.description;

